python -c "import subprocess, urllib.request, json
r = subprocess.run(['where', 'scrcpy'], capture_output=True, text=True)
print('Existing scrcpy:', r.stdout.strip())
if not r.stdout.strip():
    print('Checking latest release on GitHub...')
    req = urllib.request.Request('https://api.github.com/repos/Genymobile/scrcpy/releases/latest', headers={'User-Agent': 'Mozilla/5.0'})
    try:
        with urllib.request.urlopen(req) as resp:
            data = json.loads(resp.read().decode())
            print('Latest Tag:', data['tag_name'])
            for asset in data.get('assets', []):
                if 'win64' in asset['name'] and asset['name'].endswith('.zip'):
                    print('Download URL:', asset['browser_download_url'])
    except Exception as e:
        print('Error checking GitHub API:', e)
